-- Write cost of 10 text, 10 number and 10 date slots (30 partial indexes), by how many slots a row fills.
SET search_path = multi;
DROP TABLE IF EXISTS w_base, w_slots30;
CREATE TABLE w_base(id uuid PRIMARY KEY, tenant_id uuid NOT NULL, list_id uuid NOT NULL, parent_id uuid, scope_id uuid NOT NULL, title varchar(1024) NOT NULL, fields jsonb NOT NULL, updated_at timestamptz NOT NULL, version bigint NOT NULL);
CREATE TABLE w_slots30(LIKE w_base INCLUDING ALL, t1 varchar(255), t2 varchar(255), t3 varchar(255), t4 varchar(255), t5 varchar(255), t6 varchar(255), t7 varchar(255), t8 varchar(255), t9 varchar(255), t10 varchar(255), n1 numeric, n2 numeric, n3 numeric, n4 numeric, n5 numeric, n6 numeric, n7 numeric, n8 numeric, n9 numeric, n10 numeric, d1 date, d2 date, d3 date, d4 date, d5 date, d6 date, d7 date, d8 date, d9 date, d10 date);
INSERT INTO w_base SELECT md5('w' || n)::uuid, md5('tenant')::uuid, md5('list-w' || (n % 2))::uuid, NULL, md5('list-w' || (n % 2))::uuid, 'Row ' || n, jsonb_build_object('a', n), now(), 1 FROM generate_series(1, 500000) n;
-- list-w0 rows fill 3 slots, list-w1 rows fill all 30
INSERT INTO w_slots30 SELECT b.*, CASE WHEN n % 2 = 1 OR 1 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 2 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 3 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 4 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 5 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 6 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 7 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 8 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 9 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 10 = 1 THEN 'v' || (n % 50) END, CASE WHEN n % 2 = 1 OR 1 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 2 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 3 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 4 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 5 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 6 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 7 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 8 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 9 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 10 = 1 THEN n % 1000 END, CASE WHEN n % 2 = 1 OR 1 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 2 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 3 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 4 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 5 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 6 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 7 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 8 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 9 = 1 THEN date '2024-01-01' + n % 500 END, CASE WHEN n % 2 = 1 OR 10 = 1 THEN date '2024-01-01' + n % 500 END FROM w_base b, LATERAL (SELECT substr(b.title, 5)::int AS n) x;
CREATE INDEX ON w_base(list_id, parent_id); CREATE INDEX ON w_base(scope_id, id); CREATE INDEX ON w_base(tenant_id); CREATE INDEX ON w_base USING gin (fields jsonb_path_ops);
CREATE INDEX ON w_slots30(list_id, parent_id); CREATE INDEX ON w_slots30(scope_id, id); CREATE INDEX ON w_slots30(tenant_id); CREATE INDEX ON w_slots30 USING gin (fields jsonb_path_ops);
CREATE INDEX ON w_slots30(list_id, t1, id) WHERE t1 IS NOT NULL;
CREATE INDEX ON w_slots30(list_id, t2, id) WHERE t2 IS NOT NULL;
